export const envelope = [17, 30, 25];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;
  const seatY = 7;

  function set(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ) {
      api.set(x, y, z, block);
    }
  }

  function getBase(blockStr) {
    return (blockStr || "").split("[")[0];
  }

  const woodPlanks = api.theme.wood.planks || "minecraft:oak_planks";
  const woodLog = api.theme.wood.log || "minecraft:oak_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_oak_log";
  const woodStairs = api.theme.wood.stairs || "minecraft:oak_stairs";
  const woodSlab = api.theme.wood.slab || "minecraft:oak_slab";
  const woodFence = api.theme.wood.fence || "minecraft:oak_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:oak_trapdoor";

  const logBase = getBase(woodLog);
  const strippedBase = getBase(woodStripped);
  const stairsBase = getBase(woodStairs);
  const slabBase = getBase(woodSlab);
  const trapdoorBase = getBase(woodTrapdoor);

  const logY = `${logBase}[axis=y]`;
  const logX = `${logBase}[axis=x]`;
  const logZ = `${logBase}[axis=z]`;

  const strippedY = `${strippedBase}[axis=y]`;
  const strippedX = `${strippedBase}[axis=x]`;
  const strippedZ = `${strippedBase}[axis=z]`;

  const slabBottom = `${slabBase}[type=bottom]`;
  const slabTop = `${slabBase}[type=top]`;

  function stair(facing, half = "bottom", shape = "straight") {
    return `${stairsBase}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function trapdoor(facing = "north", half = "bottom", open = false) {
    return `${trapdoorBase}[facing=${facing},half=${half},open=${open}]`;
  }

  const plinth = api.theme.ground.plinth || "minecraft:stone_bricks";

  // -------------------------------------------------------------
  // 1. Ground Conformance & Footprint Foundations
  // -------------------------------------------------------------
  const groundCols = new Set();
  function markCol(x, z) {
    groundCols.add(`${x},${z}`);
  }

  // Mark all columns touched by wheels, chassis runners, crossbeams, and tow gear
  for (let z = 4; z <= 21; z++) {
    markCol(4, z);
    markCol(8, z);
    markCol(12, z);
  }
  for (let z = 6; z <= 19; z++) {
    markCol(3, z);
    markCol(13, z);
  }
  for (const z of [5, 8, 11, 14, 17, 20]) {
    for (let x = 3; x <= 13; x++) markCol(x, z);
  }
  for (let z = 0; z <= 3; z++) {
    for (let x = 4; x <= 12; x++) markCol(x, z);
  }
  // Wheel contact areas
  for (const wz of [7, 8, 9, 16, 17, 18]) {
    for (let x = 2; x <= 4; x++) markCol(x, wz);
    for (let x = 12; x <= 14; x++) markCol(x, wz);
  }

  for (const entry of groundCols) {
    const [cx, cz] = entry.split(",").map(Number);
    const gh = seatY + api.heightAt(cx, cz);
    const startY = Math.max(0, gh);
    if (gh < seatY) {
      for (let y = startY; y <= seatY; y++) {
        const isWheelCol = (cx <= 3 || cx >= 13) && ((cz >= 7 && cz <= 9) || (cz >= 16 && cz <= 18));
        if (isWheelCol) {
          set(cx, y, cz, y === startY ? plinth : logZ);
        } else {
          set(cx, y, cz, y % 2 === 0 ? logX : logZ);
        }
      }
    }
  }

  // -------------------------------------------------------------
  // 2. Chassis Sledge & Towing Tackle (y = seatY + 1)
  // -------------------------------------------------------------
  const chassisY = seatY + 1;

  // Main lengthwise runners
  for (let z = 4; z <= 21; z++) {
    set(8, chassisY, z, strippedZ);
    set(4, chassisY, z, logZ);
    set(12, chassisY, z, logZ);
  }
  for (let z = 6; z <= 19; z++) {
    set(3, chassisY, z, logZ);
    set(13, chassisY, z, logZ);
  }

  // Transverse heavy crossbeams
  for (const z of [5, 8, 11, 14, 17, 20]) {
    for (let x = 3; x <= 13; x++) {
      set(x, chassisY, z, logX);
    }
  }

  // Platform decking beneath leg mounts
  for (let z = 6; z <= 19; z++) {
    for (let x = 4; x <= 12; x++) {
      if ((z >= 7 && z <= 9) || (z >= 16 && z <= 18)) {
        set(x, chassisY, z, woodPlanks);
      }
    }
  }

  // Front towing harness & haulage cables
  for (let z = 0; z <= 3; z++) {
    set(5, chassisY, z, "minecraft:chain");
    set(8, chassisY, z, strippedZ);
    set(11, chassisY, z, "minecraft:chain");
  }
  for (let x = 4; x <= 12; x++) {
    set(x, chassisY, 0, logX);
  }
  set(4, chassisY + 1, 0, woodFence);
  set(8, chassisY + 1, 0, woodFence);
  set(12, chassisY + 1, 0, woodFence);

  // -------------------------------------------------------------
  // 3. Four Colossal Wheeled Bogies
  // -------------------------------------------------------------
  function buildWheel(cx, cy, cz, isLeft) {
    const axleMin = isLeft ? 2 : 12;
    const axleMax = isLeft ? 4 : 14;
    for (let x = axleMin; x <= axleMax; x++) {
      set(x, cy, cz, strippedX);
    }

    set(cx, cy, cz, strippedX);
    set(cx, cy + 1, cz, woodPlanks);
    set(cx, cy + 1, cz - 1, stair("south", "top"));
    set(cx, cy + 1, cz + 1, stair("north", "top"));

    set(cx, cy - 1, cz, woodPlanks);
    set(cx, cy - 1, cz - 1, stair("south", "bottom"));
    set(cx, cy - 1, cz + 1, stair("north", "bottom"));

    set(cx, cy, cz - 1, woodPlanks);
    set(cx, cy, cz + 1, woodPlanks);

    set(cx + (isLeft ? -1 : 1), cy, cz, trapdoor(isLeft ? "east" : "west", "bottom", false));

    // Wheel chocks on the track
    set(cx, cy - 1, cz - 2, stair("south", "bottom"));
    set(cx, cy - 1, cz + 2, stair("north", "bottom"));
  }

  buildWheel(2, chassisY, 8, true);
  buildWheel(14, chassisY, 8, false);
  buildWheel(2, chassisY, 17, true);
  buildWheel(14, chassisY, 17, false);

  // -------------------------------------------------------------
  // 4. Four Massive Carpentered Legs (y = seatY + 1 to seatY + 7)
  // -------------------------------------------------------------
  function buildLeg(centerX, centerZ, isRear) {
    // Hoof / Plinth Base
    for (let x = centerX - 1; x <= centerX + 1; x++) {
      for (let z = centerZ - 1; z <= centerZ + 1; z++) {
        set(x, seatY + 1, z, woodPlanks);
        set(x, seatY + 2, z, strippedY);
      }
    }

    // Lower Leg Shaft
    for (let y = seatY + 3; y <= seatY + 4; y++) {
      set(centerX, y, centerZ, strippedY);
      set(centerX - 1, y, centerZ, woodPlanks);
      set(centerX + 1, y, centerZ, woodPlanks);
      set(centerX, y, centerZ - 1, woodPlanks);
      set(centerX, y, centerZ + 1, woodPlanks);
    }

    // Knee / Hock Articulation
    const yJoint = seatY + 5;
    if (!isRear) {
      // Front knee stepped slightly forward
      for (let x = centerX - 1; x <= centerX + 1; x++) {
        set(x, yJoint, centerZ, strippedY);
        set(x, yJoint, centerZ - 1, woodPlanks);
      }
      set(centerX, yJoint, centerZ - 1, stair("north", "bottom"));
    } else {
      // Rear hock stepped back
      for (let x = centerX - 1; x <= centerX + 1; x++) {
        set(x, yJoint, centerZ, strippedY);
        set(x, yJoint, centerZ + 1, woodPlanks);
      }
      set(centerX, yJoint, centerZ + 1, stair("south", "bottom"));
    }

    // Upper Leg / Thigh expanding into belly
    for (let y = seatY + 6; y <= seatY + 7; y++) {
      for (let x = centerX - 1; x <= centerX + 1; x++) {
        for (let z = centerZ - 1; z <= centerZ + 1; z++) {
          set(x, y, z, (x === centerX && z === centerZ) ? strippedY : woodPlanks);
        }
      }
    }
  }

  buildLeg(5, 8, false);
  buildLeg(11, 8, false);
  buildLeg(5, 17, true);
  buildLeg(11, 17, true);

  // Ship-knee structural braces between legs and chassis
  set(6, seatY + 2, 8, stair("west", "bottom"));
  set(10, seatY + 2, 8, stair("east", "bottom"));
  set(6, seatY + 2, 17, stair("west", "bottom"));
  set(10, seatY + 2, 17, stair("east", "bottom"));

  // -------------------------------------------------------------
  // 5. Hollow Torso / Soldier Belly (y = seatY + 6 to seatY + 15)
  // -------------------------------------------------------------
  const bellyCenterY = seatY + 10.5;

  for (let z = 6; z <= 20; z++) {
    const t = (z - 6) / 14;
    // Calculate barrel radius along body curve
    let rx = 4.8 - 1.8 * Math.pow(t - 0.45, 2) * 4;
    let ry = 4.6 - 1.2 * Math.pow(t - 0.45, 2) * 4;
    if (z === 6) { rx = 3.2; ry = 3.6; }
    if (z === 20) { rx = 3.4; ry = 3.5; }

    for (let x = 3; x <= 13; x++) {
      for (let y = seatY + 6; y <= seatY + 15; y++) {
        const dx = (x - 8) / rx;
        const dy = (y - bellyCenterY) / ry;
        const distOuter = dx * dx + dy * dy;

        if (distOuter <= 1.08) {
          // Inner cavity check for the Greek soldier hideout
          const inHollowZ = z >= 9 && z <= 17;
          const inHollowY = y >= seatY + 7 && y <= seatY + 12;
          const dxInner = (x - 8) / (rx - 1.15);
          const dyInner = (y - bellyCenterY) / (ry - 1.15);
          const distInner = dxInner * dxInner + dyInner * dyInner;

          if (inHollowZ && inHollowY && distInner <= 0.92) {
            // Leave open air interior!
          } else {
            // Solid wooden hull construction
            if (z % 2 === 0 && (x === Math.floor(8 - rx) || x === Math.ceil(8 + rx) || y === Math.ceil(bellyCenterY + ry))) {
              set(x, y, z, logY);
            } else if (y === seatY + 6) {
              set(x, y, z, woodPlanks);
            } else {
              set(x, y, z, woodPlanks);
            }
          }
        }
      }
    }
  }

  // Solid interior floor
  for (let z = 9; z <= 17; z++) {
    for (let x = 6; x <= 10; x++) {
      set(x, seatY + 6, z, woodPlanks);
      set(x, seatY + 13, z, woodPlanks);
    }
  }

  // Concealed trapdoor in the belly floor
  set(8, seatY + 6, 13, trapdoor("north", "bottom", false));
  // Drop chute and escape ladder under the belly hatch
  for (let y = seatY + 2; y <= seatY + 5; y++) {
    set(8, y, 13, "minecraft:air");
    set(8, y, 12, "minecraft:ladder[facing=south]");
  }

  // Soldier peep-holes along the flanks
  set(3, seatY + 9, 11, trapdoor("west", "top", false));
  set(3, seatY + 9, 15, trapdoor("west", "top", false));
  set(13, seatY + 9, 11, trapdoor("east", "top", false));
  set(13, seatY + 9, 15, trapdoor("east", "top", false));

  // Dim secret lantern hung from inner ceiling
  set(8, seatY + 12, 13, "minecraft:lantern[hanging=true]");

  // -------------------------------------------------------------
  // 6. Chest, Withers & Arching Neck
  // -------------------------------------------------------------
  // Muscular ship-prow chest
  for (let y = seatY + 8; y <= seatY + 14; y++) {
    set(8, y, 5, strippedZ);
    set(7, y, 5, woodPlanks);
    set(9, y, 5, woodPlanks);
    set(8, y, 4, woodPlanks);
  }
  set(8, seatY + 9, 4, stair("south", "bottom"));
  set(8, seatY + 10, 4, stair("south", "bottom"));
  set(8, seatY + 11, 4, stair("south", "bottom"));

  // Withers (raised spine ridge)
  for (let z = 6; z <= 8; z++) {
    set(8, seatY + 14, z, strippedZ);
    set(8, seatY + 15, z, woodPlanks);
  }
  set(8, seatY + 16, 7, slabBottom);

  // Powerful forward-angled neck
  const neckLayers = [
    { y: seatY + 12, zMin: 5, zMax: 7, xMin: 6, xMax: 10 },
    { y: seatY + 13, zMin: 5, zMax: 7, xMin: 6, xMax: 10 },
    { y: seatY + 14, zMin: 4, zMax: 6, xMin: 6, xMax: 10 },
    { y: seatY + 15, zMin: 4, zMax: 6, xMin: 6, xMax: 10 },
    { y: seatY + 16, zMin: 3, zMax: 5, xMin: 6, xMax: 10 },
    { y: seatY + 17, zMin: 3, zMax: 5, xMin: 7, xMax: 9 },
    { y: seatY + 18, zMin: 2, zMax: 4, xMin: 7, xMax: 9 },
    { y: seatY + 19, zMin: 2, zMax: 4, xMin: 7, xMax: 9 }
  ];

  for (const layer of neckLayers) {
    for (let z = layer.zMin; z <= layer.zMax; z++) {
      for (let x = layer.xMin; x <= layer.xMax; x++) {
        set(x, layer.y, z, (x === 8) ? strippedZ : woodPlanks);
      }
    }
  }

  // Trojan mane crest along dorsal spine
  set(8, seatY + 16, 7, stair("south", "bottom"));
  set(8, seatY + 17, 6, stair("south", "bottom"));
  set(8, seatY + 18, 5, stair("south", "bottom"));
  set(8, seatY + 19, 4, stair("south", "bottom"));
  set(8, seatY + 20, 3, stair("south", "bottom"));
  set(8, seatY + 20, 4, slabBottom);

  // Mane fringe details on left and right sides
  set(7, seatY + 18, 5, stair("east", "bottom"));
  set(9, seatY + 18, 5, stair("west", "bottom"));
  set(7, seatY + 19, 4, stair("east", "bottom"));
  set(9, seatY + 19, 4, stair("west", "bottom"));

  // -------------------------------------------------------------
  // 7. Head, Muzzle, Bridle & Upright Ears
  // -------------------------------------------------------------
  // Jowl and Mandible
  for (let x = 6; x <= 10; x++) {
    for (let z = 3; z <= 5; z++) {
      set(x, seatY + 16, z, woodPlanks);
      set(x, seatY + 17, z, woodPlanks);
    }
  }
  set(8, seatY + 16, 3, stair("north", "top"));

  // Forehead & Brow
  for (let x = 7; x <= 9; x++) {
    for (let z = 2; z <= 4; z++) {
      set(x, seatY + 18, z, woodPlanks);
      set(x, seatY + 19, z, woodPlanks);
      set(x, seatY + 20, z, woodPlanks);
    }
  }

  // Snout & Nostrils
  for (let x = 7; x <= 9; x++) {
    set(x, seatY + 16, 2, woodPlanks);
    set(x, seatY + 17, 2, woodPlanks);
    set(x, seatY + 18, 2, woodPlanks);
  }
  set(7, seatY + 16, 1, stair("north", "top"));
  set(8, seatY + 16, 1, woodPlanks);
  set(9, seatY + 16, 1, stair("north", "top"));
  set(7, seatY + 17, 1, woodPlanks);
  set(8, seatY + 17, 1, woodPlanks);
  set(9, seatY + 17, 1, woodPlanks);
  set(8, seatY + 18, 1, stair("north", "bottom"));
  set(7, seatY + 18, 1, slabBottom);
  set(9, seatY + 18, 1, slabBottom);

  // Carved eye sockets
  set(6, seatY + 18, 3, stair("west", "bottom"));
  set(10, seatY + 18, 3, stair("east", "bottom"));

  // Ceremonial Bit and Bridle fittings
  set(6, seatY + 16, 2, "minecraft:iron_bars");
  set(10, seatY + 16, 2, "minecraft:iron_bars");
  set(6, seatY + 17, 3, trapdoor("west", "bottom", false));
  set(10, seatY + 17, 3, trapdoor("east", "bottom", false));

  // Upright Ears
  set(6, seatY + 21, 3, stair("south", "bottom"));
  set(6, seatY + 22, 3, woodFence);
  set(10, seatY + 21, 3, stair("south", "bottom"));
  set(10, seatY + 22, 3, woodFence);

  // Forelock crest between ears
  set(8, seatY + 21, 2, slabBottom);

  // -------------------------------------------------------------
  // 8. Haunches & Braided Flowing Tail
  // -------------------------------------------------------------
  // Rump haunch mass
  for (let z = 18; z <= 20; z++) {
    for (let x = 6; x <= 10; x++) {
      for (let y = seatY + 11; y <= seatY + 14; y++) {
        set(x, y, z, woodPlanks);
      }
    }
  }

  // Sculpted Tail
  set(8, seatY + 14, 20, strippedZ);
  set(8, seatY + 13, 21, logZ);
  set(8, seatY + 14, 21, stair("north", "bottom"));

  set(8, seatY + 12, 21, woodPlanks);
  set(8, seatY + 12, 22, woodPlanks);

  set(7, seatY + 11, 22, stair("east", "bottom"));
  set(8, seatY + 11, 22, woodPlanks);
  set(9, seatY + 11, 22, stair("west", "bottom"));

  set(7, seatY + 10, 22, woodPlanks);
  set(8, seatY + 10, 22, strippedY);
  set(9, seatY + 10, 22, woodPlanks);

  set(8, seatY + 9, 22, stair("south", "top"));
  set(8, seatY + 8, 22, woodFence);
  set(8, seatY + 7, 22, woodFence);
  set(8, seatY + 6, 22, woodFence);

  return {
    name: "trojan_horse",
    seatY: seatY,
    anchors: {
      front: [8, seatY + 1, 0],
      door: [8, seatY + 1, 5],
      belly_hatch: [8, seatY + 6, 13]
    },
    interiors: [
      {
        min: [6, seatY + 7, 10],
        max: [10, seatY + 12, 16],
        kind: "quarters"
      }
    ]
  };
}
